<?php
/** Explains probable duplicate optimization without changing another plugin. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Diagnostics;
final class OptimizationConflictDetector { public function detect( array $active_plugins, array $npe_features = array() ): array { $known = array( 'wp-rocket' => array( 'page_cache', 'css', 'javascript', 'defer' ), 'w3-total-cache' => array( 'page_cache', 'css', 'javascript' ), 'autoptimize' => array( 'css', 'javascript', 'defer' ), 'litespeed-cache' => array( 'page_cache', 'css', 'javascript', 'defer', 'lazy' ) ); $owners = array(); foreach ( $active_plugins as $plugin ) { foreach ( $known as $needle => $features ) { if ( false !== stripos( (string) $plugin, $needle ) ) { foreach ( $features as $feature ) { $owners[ $feature ][] = $needle; } } } } foreach ( $npe_features as $feature => $enabled ) { if ( $enabled ) { $owners[ $feature ][] = 'npe'; } } $conflicts = array(); foreach ( $owners as $feature => $feature_owners ) { if ( count( array_unique( $feature_owners ) ) > 1 ) { $conflicts[] = array( 'feature' => $feature, 'owners' => array_values( array_unique( $feature_owners ) ), 'action' => 'Choose one owner; NPE will not disable another plugin.' ); } } return $conflicts; } }
